function analyticsBurnCurve(){const values=[0,0,900000,900000,2600000,2600000,4300000,4300000,6200000,6200000,8000000,8000000,9500000,9500000,10600000,10600000,12100000,12100000,14000000,14000000,16300000,16300000,18400000,18400000,20400000,20400000,22400000,22400000,protocolData.burned,protocolData.burned];const points=values.map((v,i)=>((i/(values.length-1))*600).toFixed(1)+','+(150-v/protocolData.burned*125).toFixed(1)).join(' ');return '<svg class="analytics-burn-curve" viewBox="0 0 600 170" role="img" aria-label="Illustrative cumulative BLINK burns from launch to September 7: 24,618,240 tokens"><path class="an-grid-line" d="M0 25H600M0 87H600M0 150H600"/><polygon points="0,150 '+points+' 600,150" fill="#8f7bef" fill-opacity=".09"/><polyline points="'+points+'" fill="none" stroke="#9b87fa" stroke-width="2.5" vector-effect="non-scaling-stroke"/><circle cx="600" cy="25" r="4" fill="#b8a9ff"/></svg><div class="analytics-axis"><span>Launch</span><span>Jul</span><span>Aug</span><span>Sep 7</span></div>'}
