document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.analyticsPeriod&&['24h','all'].includes(b.dataset.analyticsPeriod)){analyticsState.period=b.dataset.analyticsPeriod;route({keepScroll:true})}if(b.hasAttribute('data-analytics-source'))analyticsSources();if(b.hasAttribute('data-analytics-day'))analyticsSelectDay(Number(b.dataset.analyticsDay));if(b.dataset.analyticsBalance){const group=protocolData.balances.find(g=>g.id===b.dataset.analyticsBalance);if(group)openModal(group.title,'<p>'+group.description+'</p><div class="analytics-modal-total">'+anMoney(analyticsBalanceTotal(group))+'</div><p>Snapshot balance in USD equivalent, including all assets shown in the breakdown.</p><p class="form-note">Example data · no live address connected. This is separate from Workroom’s preview POWERPLAY treasury.</p>')}if(b.hasAttribute('data-analytics-burn')){const r=protocolData.burns[Number(b.dataset.analyticsBurn)];if(r)openModal('Burn record · '+r.date,'<div class="info-row"><span>BLINK removed</span><strong>'+anNumber(r.amount)+'</strong></div><div class="info-row"><span>Fees used</span><strong>'+r.eth.toFixed(2)+' ETH</strong></div><div class="info-row"><span>Transaction</span><strong>Not connected</strong></div><p class="form-note">Example record. No real burn transaction or explorer link exists for this demo.</p>')}});
