document.addEventListener('input',e=>{if(e.target.id==='market-search'){state.query=e.target.value;renderMarkets()}if(e.target.id==='thesis-search'){state.thesisQuery=e.target.value;renderTheses()}if(e.target.id==='trade-amount')updateQuote();if(e.target.closest('#launch-form'))updateLaunchPreview()});
