document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.token){navigate('token/'+b.dataset.token);return}if(b.dataset.vote){toggleIdea(b.dataset.vote,'voted');return}if(b.dataset.save){toggleIdea(b.dataset.save,'saved');return}if(b.dataset.stage){stageModal(b.dataset.stage);return}if(b.dataset.modalRoute){closeModal();navigate(b.dataset.modalRoute);return}if(b.dataset.thesisSort){state.thesisSort=b.dataset.thesisSort;document.querySelectorAll('[data-thesis-sort]').forEach(x=>{x.classList.toggle('active',x.dataset.thesisSort===state.thesisSort);x.setAttribute('aria-pressed',x.dataset.thesisSort===state.thesisSort)});renderTheses();return}if(b.dataset.side){state.tradeSide=b.dataset.side;route({keepScroll:true});return}if(b.dataset.amount){const t=currentToken();const max=state.tradeSide==='buy'?state.cash:(state.holdings[t.id]||0)*t.price;document.getElementById('trade-amount').value=b.dataset.amount==='max'?(Math.floor(max*100)/100).toFixed(2):b.dataset.amount;updateQuote();return}const action=b.dataset.action;if(action==='close-modal')closeModal();else if(action==='wallet')walletModal();else if(action==='post')postModal();else if(action==='alerts')alertsModal();else if(action==='activate-wallet'){state.wallet=true;closeModal();route({keepScroll:true});toast('Demo wallet active. You have '+money(state.cash)+' to explore.')}else if(action==='disconnect'){state.wallet=false;closeModal();route({keepScroll:true});toast('Demo wallet disconnected. Your tab’s activity is kept.')}else if(action==='open-portfolio'){closeModal();if(location.hash==='#portfolio')route();else navigate('portfolio')}else if(action==='confirm-trade')completeTrade();else if(action==='confirm-launch')completeLaunch();else if(action==='product')navigate('workroom');else if(action==='discuss'){const i=ideas.find(i=>i.token===b.dataset.discussToken);if(i)navigate('idea/'+i.id);else{postModal(currentToken().id);const textarea=document.querySelector('#idea-form textarea');textarea.value='My view on $'+currentToken().ticker+': ';}}else if(action==='explore'&&location.hash==='#markets'){e.preventDefault();document.getElementById('markets')?.scrollIntoView({behavior:'smooth'})}});
document.addEventListener('submit',e=>{if(!['trade-form','launch-form','idea-form','comment-form'].includes(e.target.id))return;e.preventDefault();if(e.target.id==='trade-form')reviewTrade();else if(e.target.id==='launch-form')reviewLaunchStudio(e.target);else if(e.target.id==='idea-form'){const data=Object.fromEntries(new FormData(e.target));if(data.title.trim().length<5||data.body.trim().length<20){document.getElementById('idea-error').textContent='Add a title of at least 5 characters and an idea of at least 20 characters.';return}const research=validateResearch(data);if(research.error){document.getElementById('idea-error').textContent=research.error;return}const i={...research,id:'post-'+Date.now().toString(36),author:'you',initials:'you',title:data.title.trim(),body:data.body.trim(),votes:1,comments:0,stage:'IDEA',age:'just now',saved:false,voted:false};ideas.unshift(i);recordCommunityActivity({type:'Thesis',idea:i.id,body:i.title});closeModal();state.thesisSort='new';navigate('idea/'+i.id);toast('Your demo idea is posted in this tab.')}else{const text=new FormData(e.target).get('comment').trim();if(text.length<3){e.target.querySelector('textarea').setCustomValidity('Write at least 3 characters.');e.target.reportValidity();e.target.querySelector('textarea').setCustomValidity('');return}const i=ideas.find(i=>i.id===e.target.dataset.idea);(i.localComments??=[]).push(text);i.comments++;route({keepScroll:true});toast('Demo comment added.')}});
const modal=document.getElementById('modal');modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});modal.addEventListener('close',()=>{document.body.style.overflow='';pendingTrade=null;pendingLaunch=null;studioState.pending=null});
