 'use strict';
 function quoteTrade({side,amount,price,cash,quantity}){
  if(!['buy','sell'].includes(side))throw new Error('Choose Buy or Sell.');
  if(!Number.isFinite(amount)||amount<=0)throw new Error('Enter an amount greater than zero.');
  if(!Number.isFinite(price)||price<=0)throw new Error('This demo market is not available.');
  if(!Number.isFinite(cash)||cash<0||!Number.isFinite(quantity)||quantity<0)throw new Error('Invalid demo balance.');
  if(side==='buy'&&amount>cash+0.0000001)throw new Error('Not enough demo USD. Try a smaller amount.');
  const soldQuantity=amount/price;
  if(side==='sell'&&soldQuantity>quantity+0.0000001)throw new Error('Not enough tokens. Try a smaller amount.');
  const fee=amount*.005;
  const tokenAmount=side==='buy'?(amount-fee)/price:soldQuantity;
  return {fee,tokenAmount,usdAmount:side==='buy'?amount:amount-fee,nextCash:Math.max(0,cash+(side==='buy'?-amount:amount-fee)),nextQuantity:Math.max(0,quantity+(side==='buy'?tokenAmount:-tokenAmount))};
 }
