function chartReadout(t,rows){const r=rows[Math.min(tokenChartState.selected,rows.length-1)],factor=tokenChartState.axis==='mcap'?t.cap/t.price:1;return '<time>'+chartTime(r.time,true)+' UTC</time><div>'+[['O',r.open],['H',r.high],['L',r.low],['C',r.close]].map(([label,value])=>'<span>'+label+' <b>'+chartPrice(value*factor)+'</b></span>').join('')+'<span>Vol <b>'+compact(r.volume)+'</b></span></div>'}
function candleSVG(t,rows){const factor=tokenChartState.axis==='mcap'?t.cap/t.price:1,min=Math.min(...rows.map(r=>r.low)),max=Math.max(...rows.map(r=>r.high)),padding=(max-min)*.12,lo=min-padding,hi=max+padding,y=v=>22+(hi-v)/(hi-lo)*216,x=i=>18+i*15.2,volMax=Math.max(...rows.map(r=>r.volume)),selected=tokenChartState.selected;
 const grid=Array.from({length:5},(_,i)=>{const value=hi-(hi-lo)*i/4,pos=y(value);return '<line x1="10" x2="750" y1="'+pos+'" y2="'+pos+'" class="candle-grid"/><text x="765" y="'+(pos+4)+'">'+chartPrice(value*factor)+'</text>'}).join('');
 const bars=rows.map((r,i)=>{const color=r.close>=r.open?'#63c4a8':'#dc8196',top=y(Math.max(r.open,r.close)),height=Math.max(1.2,Math.abs(y(r.open)-y(r.close))),volHeight=r.volume/volMax*42;return '<g><line x1="'+x(i)+'" x2="'+x(i)+'" y1="'+y(r.high)+'" y2="'+y(r.low)+'" stroke="'+color+'"/><rect x="'+(x(i)-4)+'" y="'+top+'" width="8" height="'+height+'" rx=".6" fill="'+color+'"/><rect x="'+(x(i)-4)+'" y="'+(310-volHeight)+'" width="8" height="'+volHeight+'" fill="'+color+'" opacity=".35"/><rect x="'+(x(i)-7.6)+'" y="10" width="15.2" height="305" fill="transparent" data-candle-index="'+i+'"/></g>'}).join('');
 const last=y(t.price);return '<svg class="candlestick-svg" viewBox="0 0 890 345" role="img" aria-label="Simulated '+escapeHTML(t.ticker)+' '+tokenChartState.period+' candlestick and volume chart. Use the candle selector below to inspect OHLC values.">'+grid+'<line x1="10" x2="750" y1="'+last+'" y2="'+last+'" class="candle-last"/>'+bars+'<line id="candle-cursor" x1="'+x(selected)+'" x2="'+x(selected)+'" y1="10" y2="312" class="candle-cursor"/><rect x="760" y="'+(last-11)+'" width="127" height="22" rx="4" fill="#224739"/><text x="767" y="'+(last+4)+'" class="candle-price-label">'+chartPrice(t.price*factor)+'</text>'+[0,16,32,47].map(i=>'<text x="'+x(i)+'" y="334" text-anchor="'+(i===0?'start':i===47?'end':'middle')+'">'+(tokenChartState.period==='7D'?new Date(rows[i].time).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}):chartTime(rows[i].time))+'</text>').join('')+'</svg>'}
function tokenChart(t){const rows=tokenCandles(t);if(!rows.length)return '<section class="token-chart-empty"><h2>Price history</h2><p>This demo market has just launched. No price history yet.</p><strong>'+chartPrice(t.price)+'</strong></section>';return '<div class="candle-toolbar"><div class="candle-axis" role="group" aria-label="Chart value">'+[['price','Price'],['mcap','Market cap']].map(([id,label])=>'<button type="button" data-chart-axis="'+id+'" aria-pressed="'+(tokenChartState.axis===id)+'">'+label+'</button>').join('')+'</div><div class="candle-period" role="group" aria-label="Chart time range">'+Object.keys(chartPeriods).map(p=>'<button type="button" data-chart-period="'+p+'" aria-pressed="'+(tokenChartState.period===p)+'">'+p+'</button>').join('')+'</div><span class="candle-demo">SIMULATED</span></div><div class="candle-readout" id="candle-readout">'+chartReadout(t,rows)+'</div><div class="candle-canvas">'+candleSVG(t,rows)+'</div><div class="candle-footer"><label for="candle-selection">Inspect candle</label><input id="candle-selection" type="range" min="0" max="47" step="1" value="'+tokenChartState.selected+'" aria-label="Inspect a candle" aria-valuetext="'+chartTime(rows[tokenChartState.selected].time,true)+' UTC"><span>Sep 7, 2026 · UTC</span></div>'}
function updateCandleSelection(index){if(!Number.isInteger(index)||index<0||index>47)return;const t=currentToken();if(!t)return;const rows=tokenCandles(t);if(!rows.length)return;tokenChartState.selected=index;const readout=document.getElementById('candle-readout');if(readout)readout.innerHTML=chartReadout(t,rows);const cursor=document.getElementById('candle-cursor');if(cursor){cursor.setAttribute('x1',18+index*15.2);cursor.setAttribute('x2',18+index*15.2)}const slider=document.getElementById('candle-selection');if(slider){slider.value=index;slider.setAttribute('aria-valuetext',chartTime(rows[index].time,true)+' UTC')}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const period=b.dataset.chartPeriod,axis=b.dataset.chartAxis;if(!Object.hasOwn(chartPeriods,period)&&!['price','mcap'].includes(axis))return;const t=currentToken(),host=document.getElementById('token-chart');if(!t||!host)return;if(Object.hasOwn(chartPeriods,period))tokenChartState.period=period;if(['price','mcap'].includes(axis))tokenChartState.axis=axis;tokenChartState.selected=47;host.innerHTML=tokenChart(t);document.querySelector(period?'[data-chart-period="'+period+'"]':'[data-chart-axis="'+axis+'"]')?.focus()});
